// Installs Hyperion's interceptors on the DOM and timer APIs the reference
// site intercepts, with the observers its auto-logging uses: per-node
// bookkeeping on insertion, listener registration counts, flow context
// propagation into timer and promise callbacks, and surface tracking. Every
// DOM call the app makes, React's commit included, goes through a wrapper.
import { IEventTarget, INode, IElement, IHTMLElement, ICSSStyleDeclaration, IHTMLInputElement, IWindow, IHistory } from "hyperion-dom";
import * as IPromise from "hyperion-core/src/IPromise";
import { interceptMethod } from "hyperion-core/src/MethodInterceptor";
import { guard } from "ErrorGuard";
import FlowContext from "FlowContext";

const nodeInfo = new WeakMap();
const listenerCounts = new Map();
const counters = { inserted: 0, removed: 0, attributes: 0, styleWrites: 0, timers: 0, promises: 0 };

function surfaceOf(node) {
  let current = node;
  const path = [];
  while (current) {
    const info = nodeInfo.get(current);
    if (info !== undefined) {
      for (const visited of path) {
        nodeInfo.set(visited, info);
      }
      return info;
    }
    path.push(current);
    if (current.nodeType === 1) {
      const surface = current.getAttribute("data-surface");
      if (surface !== null) {
        const created = { surface, inserted: 0 };
        for (const visited of path) {
          nodeInfo.set(visited, created);
        }
        return created;
      }
    }
    current = current.parentNode;
  }
  return null;
}

function onInserted(node) {
  counters.inserted++;
  const info = surfaceOf(this);
  if (info !== null) {
    info.inserted++;
    nodeInfo.set(node, info);
  }
}

function wrapCallbackArgument(index, name) {
  return function (args) {
    const callback = args[index];
    if (typeof callback === "function") {
      const flow = FlowContext.current();
      const guarded = guard(callback, name);
      args[index] = flow === null ? guarded : FlowContext.bind(flow, guarded);
    }
    return args;
  };
}

let installed = false;

export function installHyperion() {
  if (installed) {
    return;
  }
  installed = true;

  IEventTarget.addEventListener.onBeforeCallObserverAdd(function (type) {
    listenerCounts.set(type, (listenerCounts.get(type) ?? 0) + 1);
  });
  IEventTarget.removeEventListener.onBeforeCallObserverAdd(function (type) {
    listenerCounts.set(type, (listenerCounts.get(type) ?? 1) - 1);
  });
  IEventTarget.dispatchEvent.onBeforeCallObserverAdd(function (event) {
    FlowContext.onEvent(event);
  });

  INode.appendChild.onBeforeCallObserverAdd(onInserted);
  INode.insertBefore.onBeforeCallObserverAdd(onInserted);
  INode.replaceChild.onBeforeCallObserverAdd(onInserted);
  INode.removeChild.onBeforeCallObserverAdd(function () {
    counters.removed++;
  });
  INode.cloneNode.onAfterCallObserverAdd(function () {});

  for (const method of ["setAttribute", "removeAttribute", "toggleAttribute", "setAttributeNS"]) {
    IElement[method].onBeforeCallObserverAdd(function () {
      counters.attributes++;
    });
  }
  for (const method of ["getAttribute", "hasAttribute", "getBoundingClientRect", "getClientRects", "append", "prepend", "remove", "replaceWith", "insertAdjacentHTML", "insertAdjacentElement", "after", "before", "replaceChildren", "getElementsByTagName", "getElementsByClassName"]) {
    IElement[method].onAfterCallObserverAdd(function () {});
  }
  IElement.id.getter.onAfterCallObserverAdd(function () {});
  IElement.innerHTML.setter.onBeforeCallObserverAdd(function () {});

  IHTMLElement.style.getter.onAfterCallObserverAdd(function () {});
  for (const method of ["setProperty", "removeProperty"]) {
    ICSSStyleDeclaration[method].onBeforeCallObserverAdd(function () {
      counters.styleWrites++;
    });
  }
  ICSSStyleDeclaration.getPropertyValue.onAfterCallObserverAdd(function () {});
  IHTMLInputElement.checked.setter.onBeforeCallObserverAdd(function () {});

  IHistory.pushState.onBeforeCallObserverAdd(function (state, title, url) {
    FlowContext.onNavigation(url);
  });
  IHistory.replaceState.onBeforeCallObserverAdd(function () {});

  const setTimeoutInterceptor = interceptMethod("setTimeout", IWindow.IWindowPrototype);
  const setIntervalInterceptor = interceptMethod("setInterval", IWindow.IWindowPrototype);
  setTimeoutInterceptor.onBeforeCallMapperAdd(wrapCallbackArgument(0, "setTimeout"));
  setIntervalInterceptor.onBeforeCallMapperAdd(wrapCallbackArgument(0, "setInterval"));
  IWindow.requestAnimationFrame.onBeforeCallMapperAdd(wrapCallbackArgument(0, "requestAnimationFrame"));
  IWindow.requestIdleCallback.onBeforeCallMapperAdd(wrapCallbackArgument(0, "requestIdleCallback"));
  IWindow.fetch.onBeforeCallObserverAdd(function () {});
  IWindow.MutationObserver.onBeforeCallMapperAdd(wrapCallbackArgument(0, "MutationObserver"));
  IWindow.IntersectionObserver.onBeforeCallMapperAdd(wrapCallbackArgument(0, "IntersectionObserver"));

  IPromise.then.onBeforeCallObserverAdd(function () {
    counters.promises++;
  });
  IPromise.Catch.onBeforeCallObserverAdd(function () {});
  IPromise.Finally.onBeforeCallObserverAdd(function () {});
}

export const hyperionStats = { counters, listenerCounts };
